$secret=$dir.'/secret';file_put_contents($secret,str_repeat('ab',32));ProxyKey::useFile($secret);$key=ProxyKey::forServer($id,1);$now=(int)(microtime(true)*1000);$nonce=str_repeat('cd',16);$body=json_encode(['server_id'=>$id,'generation'=>1,'stats'=>[]]);$header=ProxyKey::requestAuth($key,$id,$now,$nonce,$body);$seen=[];$claims=0;
$claim=function($id,$nonce,$ts)use(&$seen,&$claims){$claims++;if(isset($seen[$nonce]))return false;return $seen[$nonce]=true;};
